contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(
        uint64 number_,
        uint64 timestamp_,
        uint256 basefee_,
        bytes32 hash_,
        uint64 sequenceNumber_,
        bytes32 batcherHash_,
        uint256 l1FeeOverhead_,
        uint256 l1FeeScalar_
    ) public payable {
        // Ensure the caller is NOT the depositor account.
        require(
            msg.sender != c.DEPOSITOR_ACCOUNT(),
            "caller must not be the depositor account"
        );

        // Read before-values through the public getters.
        uint64 beforeNumber = c.number(); if (__ESBMC_reverted()) return;
        uint64 beforeTimestamp = c.timestamp(); if (__ESBMC_reverted()) return;
        uint256 beforeBasefee = c.basefee(); if (__ESBMC_reverted()) return;
        bytes32 beforeHash = c.hash(); if (__ESBMC_reverted()) return;
        uint64 beforeSequenceNumber = c.sequenceNumber(); if (__ESBMC_reverted()) return;
        bytes32 beforeBatcherHash = c.batcherHash(); if (__ESBMC_reverted()) return;
        uint256 beforeL1FeeOverhead = c.l1FeeOverhead(); if (__ESBMC_reverted()) return;
        uint256 beforeL1FeeScalar = c.l1FeeScalar(); if (__ESBMC_reverted()) return;

        bool reverted;
        c.setL1BlockValues(
            number_,
            timestamp_,
            basefee_,
            hash_,
            sequenceNumber_,
            batcherHash_,
            l1FeeOverhead_,
            l1FeeScalar_
        ); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(
            reverted &&
                c.number() == beforeNumber &&
                c.timestamp() == beforeTimestamp &&
                c.basefee() == beforeBasefee &&
                c.hash() == beforeHash &&
                c.sequenceNumber() == beforeSequenceNumber &&
                c.batcherHash() == beforeBatcherHash &&
                c.l1FeeOverhead() == beforeL1FeeOverhead &&
                c.l1FeeScalar() == beforeL1FeeScalar
        );
    }

    receive() external payable {}
}

