// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    L1Block c;

    function setUp() public {
        c = new L1Block();
    }

    function _run(uint64 number_, uint64 timestamp_, uint256 basefee_, bytes32 hash_, uint64 sequenceNumber_, bytes32 batcherHash_, uint256 l1FeeOverhead_, uint256 l1FeeScalar_) internal {
        vm.assume(msg.sender != c.DEPOSITOR_ACCOUNT());
        uint64 beforeNumber;
        try c.number() returns (uint64 __r) { beforeNumber = __r; } catch { return; }
        uint64 beforeTimestamp;
        try c.timestamp() returns (uint64 __r) { beforeTimestamp = __r; } catch { return; }
        uint256 beforeBasefee;
        try c.basefee() returns (uint256 __r) { beforeBasefee = __r; } catch { return; }
        bytes32 beforeHash;
        try c.hash() returns (bytes32 __r) { beforeHash = __r; } catch { return; }
        uint64 beforeSequenceNumber;
        try c.sequenceNumber() returns (uint64 __r) { beforeSequenceNumber = __r; } catch { return; }
        bytes32 beforeBatcherHash;
        try c.batcherHash() returns (bytes32 __r) { beforeBatcherHash = __r; } catch { return; }
        uint256 beforeL1FeeOverhead;
        try c.l1FeeOverhead() returns (uint256 __r) { beforeL1FeeOverhead = __r; } catch { return; }
        uint256 beforeL1FeeScalar;
        try c.l1FeeScalar() returns (uint256 __r) { beforeL1FeeScalar = __r; } catch { return; }
        bool reverted;
        try c.setL1BlockValues(
            number_,
            timestamp_,
            basefee_,
            hash_,
            sequenceNumber_,
            batcherHash_,
            l1FeeOverhead_,
            l1FeeScalar_
        ) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted &&
                c.number() == beforeNumber &&
                c.timestamp() == beforeTimestamp &&
                c.basefee() == beforeBasefee &&
                c.hash() == beforeHash &&
                c.sequenceNumber() == beforeSequenceNumber &&
                c.batcherHash() == beforeBatcherHash &&
                c.l1FeeOverhead() == beforeL1FeeOverhead &&
                c.l1FeeScalar() == beforeL1FeeScalar);
    }

    function testFuzz_run(uint64 number_, uint64 timestamp_, uint256 basefee_, bytes32 hash_, uint64 sequenceNumber_, bytes32 batcherHash_, uint256 l1FeeOverhead_, uint256 l1FeeScalar_) public {
        _run(number_, timestamp_, basefee_, hash_, sequenceNumber_, batcherHash_, l1FeeOverhead_, l1FeeScalar_);
    }

    receive() external payable {}
}
